     xx,yy=x+dx,y+dy
     if 0<=xx<H and 0<=yy<W and a[xx][yy]==3 and (xx,yy) not in seen:
      seen.add((xx,yy)); q.append((xx,yy))
   if not edge:
    col=7 if len(comp)%2 else 2
    for x,y in comp: a[x][y]=col
 return a
